    """打印一条消息。

    Args:
        message: 要打印的内容，会自动转为字符串。
        prefix: 可选前缀，用于分类/标记输出。
        end: 行尾字符，默认换行。
    """
    text = f"{prefix}{message}" if prefix else str(message)
    print(text, end=end, flush=True)


