#include <stdio.h>

/* 打印一条消息，可带前缀 */
void print_message(const char *message, const char *prefix) {
    if (prefix != NULL) {
        printf("%s", prefix);
    }
    printf("%s\n", message);
    fflush(stdout);
}

int main(void) {
    print_message("hello world", NULL);
    print_message("任务完成", "[INFO] ");
    return 0;
}
```

